INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch13$PT128-S3-Q10$batch13$, 128, 3, 10, $batch13$Role$batch13$, $batch13$Biologists often announce that a certain kind of animal has been found capable of using tools; this usually refers to something like using a stick to hunt for ants in a log, or a stone to crack nuts. But such announcements are completely unsurprising, since all animals use tools. Birds build nests, fish hide in the mud to escape predators, and squirrels use buildings as shortcuts between trees. If an animal executes its purpose by means of an external physical object, then that object can reasonably be regarded as a tool.$batch13$, $batch13$Which one of the following most accurately describes the role played in the argument by the claim that the biologists' announcements that a certain animal has been found capable of using tools are unsurprising?$batch13$, $batch13$B$batch13$, true, $batch13$Batch 13; question text from local bank.$batch13$ FROM lr_sections s WHERE s.preptest=128 AND s.section=3 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch13$PT128-S3-Q10$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$A$batch13$, $batch13$It provides evidence that the animals' activities given as examples are purposeful.$batch13$, $batch13$Wrong Role$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT128-S3-Q10$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$A$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$B$batch13$, $batch13$It is the conclusion of the argument.$batch13$, $batch13$Correct$batch13$, true FROM lr_questions q WHERE q.qid=$batch13$PT128-S3-Q10$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$B$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$C$batch13$, $batch13$It is an assumption used by the argument to justify acceptance of a broader conception of what a tool is than that usually accepted by the biologists.$batch13$, $batch13$Wrong Role$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT128-S3-Q10$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$C$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$D$batch13$, $batch13$It calls into question the basis of the biologists' conception of a tool.$batch13$, $batch13$Wrong Role$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT128-S3-Q10$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$D$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$E$batch13$, $batch13$It addresses a weakness in the biologists' announcements that stems from their ambiguous use of the word "external."$batch13$, $batch13$Wrong Role$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT128-S3-Q10$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$E$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch13$PT128-S3-Q10$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch13$Conclusion$batch13$, $batch13$Biologists' announcements that an animal can use tools are completely unsurprising.$batch13$), (1, $batch13$Intermediate Conclusion$batch13$, $batch13$All animals use tools.$batch13$), (2, $batch13$Evidence$batch13$, $batch13$Birds build nests, fish hide in mud and squirrels use buildings as shortcuts. If an animal achieves its purpose with an external physical object, that object counts as a tool.$batch13$), (3, $batch13$Evaluate$batch13$, $batch13$"Since" marks "all animals use tools" as the reason the announcements are unsurprising. The examples and the definition of a tool support that reason. Why believe the announcements are unsurprising? Because all animals use tools. Nothing is built on the "unsurprising" claim.$batch13$), (4, $batch13$Goal$batch13$, $batch13$The claim is the conclusion.$batch13$)) v(position,label,body) WHERE q.qid=$batch13$PT128-S3-Q10$batch13$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch13$A$batch13$, $batch13$The "unsurprising" claim says nothing about whether the animals' activities are purposeful.$batch13$), ($batch13$B$batch13$, $batch13$The rest of the passage supports it, and it supports nothing else.$batch13$), ($batch13$C$batch13$, $batch13$It isn't assumed; it's argued for. The broader view of tools is the support, not the thing supported.$batch13$), ($batch13$D$batch13$, $batch13$The definition in the last sentence is what challenges the biologists' idea of a tool. The "unsurprising" claim is what that challenge supports.$batch13$), ($batch13$E$batch13$, $batch13$The biologists never use "external". The argument uses it in its own definition.$batch13$)) v(letter,body) WHERE q.qid=$batch13$PT128-S3-Q10$batch13$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
